{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "In your plan, is the amount you can sell in a given month limited to what you have in stock at the start of that month (i.e., you cannot sell more than your available inventory), or is there a separate demand/sales cap per month that I should use?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive constraints (inventory limit vs. separate sales cap), which constitutes one independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many units you can purchase in a given month (for example, a supplier capacity or budget cap), or can you buy any non-negative amount at that month's buy price?"
  ],
  "rationale": "The response asks a single clarification question regarding purchase limits, presenting a binary choice between having a cap or having no cap."
}

{
  "action": "question",
